"""续审11增量维护脚本；只写audit，源文件只读。执行前拒绝重复批次。"""
from pathlib import Path
import json, re, copy, hashlib
from collections import Counter

ROOT=Path(r'C:\Users\Administrator\Desktop\下班魔角色卡重构')
A=ROOT/'audit'
def read(n): return json.loads((A/n).read_text(encoding='utf-8'))
def write(n,v): (A/n).write_text(json.dumps(v,ensure_ascii=False,indent=2)+'\n',encoding='utf-8')
def mdwrite(n,s): (A/n).write_text(s,encoding='utf-8')
S=(ROOT/'source/下班，然后变成魔法少女_第1-282章.txt').read_text(encoding='utf-8').splitlines()
ev=read('evidence_records.json'); issues=read('issue_records.json'); missing=read('missing_records.json')
assert len(ev)==314 and max(int(x['id'][1:]) for x in issues if x['id'].startswith('C'))==103
cards={x['id']:x for x in read('card_entries.json')}
chap=read('chapter_index.json')
change={'session':'11','evidence_changes':[],'missing_changes':[],'new_evidence_ids':[],'new_issue_ids':[],'updated_existing_issue_ids':[],'new_missing_ids':[],'expanded_missing_ids':[]}
hist=read('judgment_changes.json')
def E(start,end,level,finding,quote=None):
 id=f'E{len(ev)+1:03}'; q=quote or next(n for n in range(start,end+1) if S[n-1].strip() and not S[n-1].startswith('#'))
 ev.append(dict(id=id,start=start,end=end,quote_line=q,level=level,finding=finding,session='11'));change['new_evidence_ids'].append(id)
def C(title,severity,kind,card,current,problem,evidence,level,accurate,impact,action):
 id=f'C{max(int(x["id"][1:]) for x in issues if x["id"].startswith("C"))+1:03}'
 issues.append(dict(id=id,title=title,severity=severity,kind=kind,card=card,current=current,problem=problem,evidence=evidence,level=level,accurate=accurate,impact=impact,action=action));change['new_issue_ids'].append(id)
def revise(id,addition,refs,reason,card=None,field='accurate'):
 x=next(x for x in issues if x['id']==id);before=copy.deepcopy(x)
 x[field]+=' 续审11：'+addition;x['evidence']+='；'+refs
 if card:x['card']=list(dict.fromkeys(x['card']+card))
 hist.append(dict(session='11',id=id,reason='2026-09-09；'+reason,before=before,after=copy.deepcopy(x)))
 change['updated_existing_issue_ids'].append(id)
def erevise(id,addition,reason):
 x=next(x for x in ev if x['id']==id);b=copy.deepcopy(x);x['finding']+=' 续审11回接：'+addition
 change['evidence_changes'].append(dict(session='11',record_type='evidence',id=id,reason=reason,before=b,after=copy.deepcopy(x)))
def M(category,title,refs,details,scope):
 id=f'M{len(missing)+1:03}';missing.append(dict(id=id,category=category,title=title,evidence=refs,details=details,scope=scope));change['new_missing_ids'].append(id)
def mrev(id,refs,details):
 x=next(x for x in missing if x['id']==id);b=copy.deepcopy(x);x['details']+=' 续审11：'+details;x['evidence']+=','+refs
 change['missing_changes'].append(dict(session='11',record_type='missing',id=id,reason='2026-09-09；卷二74—89连续新证补充时效与收录边界，旧判断保留并限定历史阶段。',before=b,after=copy.deepcopy(x)));change['expanded_missing_ids'].append(id)

E(20990,21143,'A（现场身份披露和各人反应）／D（人物解释）','小璐自报女儿后林承认，鸢才确认他真有女儿，并非早知她是魔法少女。小把公务短信和近身酒局猜成约会，林解释未获采信；林与小在此场同一时才听鸢的真实来意。鸢亮黑液魔杖后小才信敌对身份并主动变身，林来不及制止暴露。小的爪痕知识来自此前妖精仙人转告，不等亲见全部成员或知首领镜谈。',21045)
E(20990,21143,'A（战书与攻防发生）／D（威胁内容）／C（林的防护网推断）','鸢邀全体方亭魔法少女及外来者，称午夜银屏山爆炸；林在此自行联想到防护网，吸引兽潮的波动到76才由鸢追加说明。小先以魔力束阻离，再主动白魔全攻而被瞬间打昏，未看清攻击。不能把76两个小时、吸兽波动倒写为74已完整传达，也不能把当场能力差距当永久等级结论。',21045)
E(21144,21193,'A（醒来、父女约定及动作）／D（父亲担心与小的感受）','小约昏迷十分钟；父称已通知队伍、翠与红带队，并恳求她这次留下，承诺成长后不会再拦。她口头答应，父安排工作后离开，她又起身。75未写她通知两队；89回述证实她带夏白来，不能补成柏安消息链也已展示。父亲姿态令小觉得熟悉舒适，仍不是识破林翠同一人。',21190)
E(21194,21294,'A（仪式搭建、九人到达与私谈）／D（塞米的理想、首领法术可靠性及鸢提案）','塞米用石塔辅助有限妖精魔力，首领教的仪式不会错只是其信任。鸢喜欢城市生活，塞米厌恶贫困、求偶无果等生活；讨回响从五蜕到三蜕未成交。鸢提别干了后改提摧毁防护网、以灾害牵制国度的方案，塞米以已流血不可回头及女王年迫近催促。九道轨迹为三旧六新，人数也让敌人意外。88才完整解释鸢希望装置最终可拆；此处不可先洗成伪装威胁。',21259)
E(21295,21353,'A（相见、选择、唱名）／D（灾情预测与全部实力自述）','玛从火锅席收到电话急赶，鸢此前不认识她。翠先试查仪式被挡，鸢此时说两小时后炸山、损防护网并吸兽潮；可能重演二十年前灾害为威胁/预测。提出败后带翠白、现在跟走、九人击倒自己三种选择。源L21353报兽心解放百武成势；78解释却称百势成武，保留源文用名张力，不据76单句判卡名错误。',21353)
E(21354,21383,'A（外观、压迫与攻击）／D（玛初猜繁开、鸢的替代技术说明）','心解灰白单马尾、赤羽衣、黑巩鸟瞳与红纹；十余秒变化只有三旧队完整看清，低于蕾者精神及魔力受压。玛先误猜繁开，听鸢讲爪痕底色改变失去繁开、另造替代；78叙述才补共同发展历史。玛以本能避开骤攻不等所有旁观新人能跟上，也不采鸢全部放开自述为确无隐藏奇境。')
E(21384,21491,'A（陆红豆生平回忆）／D（师父武道评价）','陆红豆五岁灾中与父母失散，由师父救养，不等父母已证死亡。十四岁下山为生计卖艺、拒偷盗欺弱，逐步融入城市；败于残兽获天女救后寻找三年无果，十七岁返山长谈、翌日师父去世，此后才主动找天女求资质测试。不能将一次获救直接顺接立即被动接受契约，或把落伍固定成从无社会适应。')
E(21384,21491,'A（魔力辅助武道研发与职业困境）／D（传统气势理论）','师父未亲证古法气与势，陆用魔力通窍、魔装与繁开推进武道却发现高度依赖少女力量。她不热衷任务、贡献积累不足，面临未来强制退役；不是已到固定期限无条件退役。紫钻以兽力支持其继续研究和共同家园邀请。独立气性质不等整个武道成长完全不依赖魔力，回接M028/C076。')
E(21492,21544,'A（招募、派系变迁与心解沿革）／D（退役者各自诉求）','唐仍拒叛、可保国度身份研究；紫钻比武承诺仅用少女能力却暗用兽力，随后带见被迫退役者，求容颜力量者与真心护世者并存。她参与大逃亡成为干部，组织最多数百、仇国新派压过旧批；约十二年前园丁围剿十干部去五，其他幸存者分驻基地/间界，不能写成干部死亡过半。改底色已使旧花级失繁开，心解是后来以单一残兽魔力重研的相近替代。原繁开百武乘势、新心解百势成武，与76报号不一致；赤鸢异称不另建人物。',21541)
E(21545,21578,'A（多线封路、救援失败与贯胸）','鸢以黑雾武影压九人，新人魔装难用；翠丝线数次救人后被敌从固定轨迹预判，在两退路线角平分线上截住并于78章末贯穿胸部。不能把动作起点全部移入79，也不能忽略预设撤离线会被识破的战术成本。',21577)
E(21579,21615,'A（本相/魔力源说明及当次伤害）／D（翠对伤势安抚）','少女躯体由魔力构造，胸口并非普通人同款必死弱点；本相受威胁包括耗尽魔力、灵魂攻击和源损。翠最后移动魔力源成功，未被直接伤源，但侵入兽魔扩大伤口、修复加耗。玛以酒火迫退并接救，翠只向小璐耳语计划；不能把小听到的内容给全队，或把未伤源等同全无风险。')
E(21616,21679,'A（白兽形、救援与众人见证）／C（翠与敌方推测）','白黑绿兽形拦鸢救红，随后腹部中掌被击飞、红接住。叙述称此前此姿态除翠无人见过，当前至少此场其余人首次亲见；不只柏安学生新增见闻。鸢因此辨认被要求带走的白，不能升为掌握其全部身世。翠由丝线反击造成的细微犹豫猜能力弱点，尚未完全掌握；需红再次复制剪并在关键时配合，玛应要求繁开。',21616)
E(21643,21679,'A（试探操作与未造成有效伤害）／C（翠对心解弱点的推断）','翠借被贯胸瞬间以丝反切手臂，切中但未有效伤害；鸢一瞬犹豫促她猜能力弱点。她明确尚不能据此知道真相，复制的第二剪又不稳定，须先知本质再用在关键处；因而此时才要求玛繁开。敌方吸取早战教训不再解释机制，不能写成翠已直接获得完整能力说明。',21675)
E(21680,21766,'A（情热演化、情绪和言语习惯的叙述）／E（苏的渣男化评价）','情热基础为透明高脚杯，情绪决定液态魔力效果；平稳通常治疗/强化，极端利杀伤。早期情绪随机导致敌治我伤，她读心理和情绪管理书并调自身心态；由早期直口自夸辱骂逐渐改为含蓄自夸、阴阳怪气，自信底层保留。苏对变化的戏称只是他人评价，不是客观恋爱行为定义。',21752)
E(21680,21766,'A（繁开与奇境分别展开、酒量互倒）／D/E（红对翠状态的担心、翠的相对解释）','玛先繁开换衣再同步展开奇境，二者组合令本相映杯。小满四色、夏半杯、白绿泡、翠杯底少量蓝；红担忧而把自己超过半杯倒给翠，只增加薄层，翠说相对普通少女并没那么糟并还酒。杯内比例不能脱离个人容量绝对判生命濒危；误判主要由红发出，不是玛给出已验证生命结论。翠仍有伤，不反向说健康无耗。',21752)
E(21767,21838,'A（鸢试饮、悲情生效与协同操作）／D（规则解释）','鸢先以气护内器试饮，酒不入腹而回杯，才猜本相投影。情绪干预无需真正喝下；繁开允许精细调杯内魔力、不再被自身情绪随机决定，叠奇境才能把杯投给别人实施对应影响，目标魔力越多持续越短。玛调情绪、红术式与翠刀丝诱导受伤；红展开忆海书库借剪，翠借丝为媒介剪气，非红直接剪或剪掉势。',21838)
E(21839,21876,'A（掉层、六人突围和借回兽源）','首次有效受创使鸢杯少一层；六名新人共同突破，随后才拆成两人查塔、四人追塞米。鸢斩开屋顶不等奇境规则解除，81也未磨尽心解。章末翠已将兽源借回用作探测器，鸢这时才看见；不推翻39成交或69报告当时事实，也不让白狼同步得知新的持有人。',21874)
E(21877,21988,'A（石塔前分工、追逐、兽化和蓝月）／D（少女知识与塞米自述）','塞米准备启仪被小白焰打断，先逃后怕失职责罚而返战；四新人追、夏与白蓟留下检查塔，非只两人从主战突围。含羞草从姐姐听说妖精不能背叛王庭，木先以为不想背叛；此是传闻知识而非普适事实。塞米称自己来自间界，白闻兽味后众人见独眼双尾巨猫与蓝月；理智仍在不能仅据此推间界出生为充分因果。')
E(21989,22090,'A（间界生活与参战回忆）／D（大杰克说可离开、塞米对家园与战争理解）','间界妖精贫荒、天灾残兽侵扰，塞米无力离开而怨故乡；纯血家长大杰克自称随时能带全族离开却不愿弃家。不能统称妖精物理上无法离故土，也不能以大杰克自称可行断所有人随意通行。塞米参与使徒提供兽力后的花园防卫战，二十年前战中重伤昏迷；战争起因只说似乎冲突，不造完整责任链。')
E(21989,22090,'A（塞米与独臂少女互相救护、强退及回返）／D（少女家园愿望）','塞米曾在战中伤害少女本相，此后却被她私藏照护、称猫猫并相伴旅行。魔事院因她伤后战力下降强退，同时提出财富、后方工作和子女优先资质安排；她仍抗拒被带走，三日后兽纹手复原、猫瞳而回，最终以黑猫名返间界成为副首领。塞米共享的是这名少女的家园梦想，不能只留白狼给理想。此章未明说妮娜姓名、左右手和义肢材料，须回接旧末段证据，不把读者全身份自动给其他人物。',22072)
E(22091,22177,'A（分隔战况及心解客观补解）／C/D（小的等级猜测、鸢胜负评价）','小只觉同伴感知消失，不等确认他人死亡；猜敌相当蜕，86叙述实际半蜕。塞米问与矢关系，她答队友保密，仍不知男身。半空战无处借力、先用白焰长矛尚非魔装。主场仍近午夜，鸢心解只余半杯：本章叙述确认初满势、受创不可逆降到临界崩，修正79尚猜阶段，不把机制早给所有旁观者。鸢称旧队全员健全或已输为评价。')
E(22178,22283,'A（实际章节、王钥初次析出与操作失误）','卷二85无副题，实写巢内小璐恶战及王钥首次觉醒：白权杖多晶，转护卫时白晶暗、浅蓝晶亮并成枪；初次挥枪绊地摔。没有卡102所说湖畔春天第二祭子回溯。卷一85的兵触三推断与截杀不能跨卷移植，更不能换成夏凉蓝冲击击杀。能力名称不等初始熟练度。')
E(22178,22283,'A（含羞草观察、小璐防御及争论）／C（敌级与同伴耐力推测）／D（敌我立场）','含羞草先怀疑空间/认知术式，尝试铃鼓感知；推同伴能撑多久不是客观战力。小被击重伤仍躲藏找队友，与塞米争国度保护和恐怖行动；不将双方正义论合成作者裁决。魔杖替她抵挡约八九成力；魔杖雏形通常随成长变强的叙述不等任意阶级固定能挡多少次攻击。')
E(22284,22409,'A（魔装评级、初析恢复、护卫实效）／C（复杂度与潜力假说）／F（未展形态）','魔装评级是资格认证多维项目并可随成长变动，形态复杂度与潜力关系只是通行假说，不能当确定强度次序。小第一次析出王钥恢复此前全部魔力，仅本次初析，不是收放即无限回蓝。护卫改变魔力性质，制导与穿刺需丝线锚定且魔力足够，不能省略供魔前缀变绝对刺穿。此时基础权杖未显别的能力，不等永久无功能；其它晶石未知。',22400)
E(22284,22409,'A（小的失误、策略与敌方退避）／C/D（塞米错误解释）','塞米一度猜宝石权杖附体或芽级繁开，后来才认种升芽；它实际半蜕且因防未知魔装而保留力量，不能简化为芽级面板压倒半蜕。小丝绑自己、枪绊脚，脑内知识不等熟练；临场仿翠留下退线，有真实失误也有保留制导能力的计划。最后枪绕尾追独眼，塞米闭眼消失规避，不是已被刺瞎/当场击杀。',22398)
E(22411,22570,'A（反复实验、误认纠正与广播）／C→B（含羞对规则的假设获实测支持）','含羞闭眼听同伴，小睁眼能见她；听小说芽击退半蜕误当伪装敌，逃跑后经魔力感知才改判，不能记作永远精准判断。通过两人逐次睁闭眼实验，确认同状态互不感知、异状态可互感的操作规律。月光/看蓝月致认知干扰为早猜，未成最终机制。拍眼声波探到异化巢边并近耗尽，广播三遍让战斗者发信号后闭眼、非战斗者先寻信号再闭眼；小保持睁眼接应。空间超过原山只是她的感知判断，不能简化为所有人一起闭眼即可互见。',22542)
E(22571,22599,'A（白的对战表现与小的局部获知）／D/E（塞米感受）','塞米按首领点名追白，虽规则有利一时不伤，仍被兽魔同类不克、魔量与术式、搏命打法及魔装辅助拖住。白按广播发弹、闭眼，小才赶到询问是否被敌施手脚，白只答与本次无关。她的形态已在79被小看见，不等当时已理解成因；现在也未讲祭子身世。木赶来、含羞近耗尽，小白并肩并不证明四人同战力同知识。',22593)
E(22601,22658,'A（检查拆塔与领队讨论）／D/C（同伴评价、推测）','夏怕塔是炸弹，白蓟先查无内部供储魔认辅助装置才拆纹；未盲拆也非两人在81已经拆完。两人见远方巢/主场变化但不亲历所有能力，小在战中已升芽，夏此时仍想将来觉醒。白蓟误以夏是同期领队，夏说现队长翠、同期可能小但不会自己；柏安另有此次未来的前辈队长。责任传承讨论不是正式任命夏或小，也不能把夏自觉偏弱等同客观排名。',22617)
E(22659,22713,'A（心解耗尽、动机叙述与认输）／D（鸢对白狼的理解及邀请保证）','88才由分层消失及叙述确认心解失效，非81杯已空。鸢真正目标仍兽源/翠/白，设塔逼战是为避免无谓屠杀：想速胜带目标走，留下其他人拆塔；若输亦可拆，并借塞米证明自己执行过。此处迟到解释补75提案及69服从，非当面向全队供述。实际危险装置不因此变不存在，败也不成投诚。翠拒邀请但承认首领条件诱人；三旧仍受伤、有余战力。',22680)
E(22714,22767,'A（范围失魔、衣装消散、退走及恢复）／C/D（翠对奇境、额外气源的推测与鸢回应）','鸢敲胸发动奇境，自己和三旧失魔，红坠地、玛杯/奇境/衣装消散；外圈触蓝月使之消失，武道肉身让鸢仍从容。翠指出是奇境，鸢称眼光准；翠关于气另源、心解增幅及首领派遣前提仍为分析，不能一并升客观。鸢认为翠有底牌，翠未用，不称全部战力已暴露。她认输仍拒被捕，未趁机掳人；数秒后众魔恢复、鸢提塞米离去。最后新年祝福声音未传达，翠看见张口不等听到完整原话。',22762)
E(22768,22902,'A（战后工作、私谈和真实心理）／D（小的推断、双方极端说辞）','一时多归据点、林私下变男安排山林清理/备案/奖励，二时多变翠找小。89回述小带夏白参战及翠路上知却忍住，限定75未叙通知范围；小已在归途报告觉醒。翠借父电话责问，随后承认小战绩重要；小要认可、更怕重失爱者而说愿代死，翠激烈拒并说若女死自己复仇后自杀，叙述连到丧妻后的意义危机，不当已执行行为。翠认识混用父亲保护与队长职责的错误。小仍误猜借自己找樱影子，提出把翠当妈；本章尚未展示答复和身份坦白。',22895)
E(22905,22978,'A（夜谈、私下披露与知识边界）／D（玛经历及风险意见）','玛等翠谈完女儿，明确知道父女秘密；她从现场兽形再追问，翠思考后这时才告诉她白是黑烬祭子。玛说不知道祭子定义，却有杀过一只的痛苦经历，不能写成此前已知白全部身世或统一祭子学说。玛提醒考试、偏见、花园审查与王庭防备；叙述说明连翠玛也可能有偏见，实际接触白后改变。知风险与承诺引导并存，不是问题已全部解决。',22939)
E(22979,23012,'A（翠的自述与新年约定）／D（人生意义判断）／E（玛人偶比喻）','翠说两年前起人生对自己无意义，以将熄木柴温暖后辈自比，玛难过并阻止继续；此是当期哀伤自我理解及旁观感受，不是永久无感情事实。转到女王年将开始，玛邀大家再到国度看烟花，翠答自己也想去；这是新的共同未来愿望，不证明考核安全或已经实现，亦修正只剩赴死的单一人格。',23011)

C('把红思与的杯量误判写成玛格丽特确认翠雀生命极差','MAJOR','能力读数／认知归属',[53,102],'卡53称玛从翠雀近底酒液判断其生命状态极差。','80实际由红因杯浅而担心，并把自己超过半杯倒入；翠杯仅升一薄层，随后解释相对普通少女没那么糟。不同容量下的比例不能直接等同生命濒危，发判断的人也被换掉。','E325、E329','A（倒杯与说明发生）／D/E（担忧和相对判断）','翠仍有真实伤势、耗魔与疼痛；应保留绝对魔量和自身剩余比例之别，不能由纠正过度担忧反判已痊愈。','NPC据错误血量读数强制濒死状态，误写玛的诊断可靠性。','后续分开可见读数、红误判、翠解释；只修审计不改卡。')
C('情热繁开与奇境的叠加条件被合并成单一步骤','MAJOR','能力机制／前置条件',[53,102],'卡53称繁开酌情热醉会展开酒吧奇境，每个人本相映成杯；102也将领域直接归于繁开。','80先繁开又同步展开奇境，81进一步明确繁开控制杯内情绪、配合奇境才把本相映射给他人。省略双层条件会把单独繁开当成自动全域他人状态控制。','E328—E330、E344','A（分次展开与实战）／D（规则解释）','无需敌人真饮酒亦可干预；情绪控制持续受目标魔量影响。屋顶被切破不等规则解除，88失魔后奇境消散是另一事件。','任意场景开繁开即全场控制，忽略目标、持续与对抗条件。','第二阶段分别表述魔装、繁开、奇境和组合；本阶段不补未证规则名或极限。')
C('鸢叛逃被简化成败给兽力后认可强者随行','MAJOR','身份转变／多重动机',[50],'卡50阶段一称败于紫钻暗用兽力，反而视作强者证明并随之叛逃。','77—78写她仍想保身份研究、拒绝叛逃，紫钻决斗违规后又带看被迫退役者；她理解不同人的诉求，才参与大规模逃亡。仅败服强者替代研究中断之惧、同类处境与后续说服，取消了真实选择过程。','E321—E323','A（回忆与行动）／D（诉求）','旧证中她自述白狼凭新力量击败自己有依据，不能反向全判虚构；新叙述使其成为动机之一而非充分因果。她仍对后来组织暴行负有参与责任。','武痴被扁平化为只认强弱、对同类全无情感，也混淆早期家园与后期仇国派。','保留旧简述来源及新增回忆，分开决斗、参访、决定和后来派系变化；有意简化路线挂U003。')
C('银屏山心解耗尽被提前到第81章并重复结算','MAJOR','战斗状态／时间错序',[102],'事件十一标第81章，却写半杯直到分层消失、百势成武终于磨空；事件十五第88章又结算一次。','81只首次掉层并让六新人突破；84仍半杯且战斗继续，88才分层消失、心解失效。把终局结果塞入81会让后续持续心解与当前状态矛盾。','E331、E335、E343','A','79怀疑→81试验受伤掉层→84叙述确认不可逆机制/半杯→88心解耗尽→另开奇境退走，按阶段写。六人共同突破后82才分流，不能只给夏白蓟突围功劳。','敌人过早失去心解后又无因恢复，后续受伤、破塔和认输因果被重复触发。','修复分阶段索引和当前能力状态；历史问题保留，不合并删掉细微区别。')
C('卷二第85章被不存在的第二祭子回溯替换','MAJOR','跨卷串写／虚构场景',[102],'事件十三称卷二85插入湖畔春天金纹首领认第二祭子、被夏凉蓝冲击击杀的延迟回溯。','连续全文显示该章实为含羞探索、小璐与塞米恶战及王钥首次析出，没有这段回溯。相近兵触三情节属于卷一85，且凶手是翠雀（C036），不能用旧事件跨卷移植为此处真实叙述。','E336、E337；E098、E099；C036','A','区分事件原发生、文本真实回忆与卡片自行回顾；主动创作回顾可以是IF，但不能冒充原著章节。小璐身份仍未因此获客观定性。','错误触发第二次敌情揭示、给夏添加击杀及知识，抹去王钥初次觉醒场景。','回接C021/C036/C009；有意保留回顾须列U003 USER_CONFIRMATION_REQUIRED，不静默改写源文。')
C('间界妖精的受困处境被绝对化为无法离开故土','MODERATE','世界规则／主观视角',[102],'事件十二概括间界贫瘠、妖精无法离开故土；并以塞米保持理智说明其间界来历。','83一面写塞米自身无力离开，一面让大杰克说能带全族走却不愿。不能从个人困境建普世禁令；出生地与保留理智之间也未展示充分机制。','E332—E334','A（回忆与言说发生）／D（大杰克可行性自述）／F（普适通行与理智机制）','保留个体能力、家园意愿和可行性自述，不反向断言妖精随时自由通行。塞米与黑猫的共同家园愿望具有具体关系来源，非仅白狼抽象口号。','封死实际可有的迁移选择，把思想与能力限制作同一禁制，旁观者凭理智便全知籍贯。','收窄绝对规则并留开放机制；与M036关系补录交叉引用。')

revise('C006','89亲子冲突明确让翠意识到把父亲劝阻直接套在队长身份上的错误；小已打算向父道歉，真正要的是战绩与依恋获认可。翠随后确实肯定战绩，不可记成始终不肯。丧妻意义危机与想保护所有后辈并存，玛邀观烟花时也表达未来愿望；不是永远纯理性导师或已完成全部亲情修复。','E317、E345—E347','迟到心理解释强化原问题并细化冲突，不以新承诺覆盖旧隔阂。',[103])
revise('C009','85/86王钥初析及魔力性质变化已出现，但未验证唯一天生兽子或完整祭子分类。卡102所谓卷二85第二祭子回溯实际不存在（C108）；卷一85原推断仍D。89玛虽杀过祭子，自称不知道定义，这时才听翠说白是祭子，不能由经历自动升级百科知情。','E336、E338—E341、E346','新能力与新增知情节点不等终极物种定性；纠正跨卷倒灌。',[102,103])
revise('C013','83先由塞米回忆补独臂少女救猫、共同旅行、拒强退与三日后兽化回返；叙述给黑猫称号但未给姓名、手别、义肢材料。卡64已有塞米关系和强退阶段，不能说整段缺失；旧末段关于身份/妹妹/义肢的已证资料仍须独立补齐，不能倒灌给83场内他人。','E333、E334','已读前半起源与末段旧证接通，收窄遗漏范围而不撤销失效未知问题。')
revise('C021','74仅午夜炸山及林推防护网，76才追加两小时与吸兽波；75未叙小通知两队，89回述只证带夏白来。77获救后寻三年、师父死才求契约，不是当场随后受测；78贯胸，79解释伤源险。81六人共同突围，82两人查塔四人追敌；84半杯、88才心解尽。85初析王钥、86解释护卫，不能整体始于86。卡102的干部死伤过半亦与78十去五不等。跨卷假回溯单列C108，终局提前见C107。','E315—E347','连续74—89校准章节、事件和认知发生时间，保留历史映射及独立实质问题。',[103])
revise('C036','卡102又把相同金纹首领欲报蛾情节移至卷二85，并将击杀改成夏凉蓝冲击；实际卷二85无此回溯（C108）。原卷一85凶手翠雀及未传出报告的判断仍有效，不能因再写版本而变成夏或麻雀灭口。','E336、E337','同一历史事件出现第三种错误主体，沿用旧ID并扩大卡定位。',[102])
revise('C035','79和87的白已主动释放兽形，出现救红、以腹承爪换攻眼及魔装支持持续战；这是后期真实战风，不再笼统否认全部搏命表现。但不能前置到卷一最初参战，更未证按治疗次数扣本相。小87才追问是否敌施手脚，白只给与此事无关的有限答复。','E326、E341','后期实战加强阶段区分，早期无源代价与错误主体问题不被撤销。',[102])
revise('C038','78贯胸时翠移源成功，79伤口侵蚀扩大并增修复魔耗，80仍因耗魔修躯负担魂痛；未伤源不等无险。81再借红复制剪和丝媒介剪气，88失魔致身体失支撑。新的伤害与消耗过程没有证明每件杰作固定扣本相，也没有因一次仍能战就证旧伤痊愈。','E324—E331、E344','将新伤、源避让、魂痛及资源条件分别回接，不新增无据按次机制。',[102])
revise('C076','77回忆用魔力通窍/魔装/繁開研发武道，不推翻气本身非魔力却说明修行成果高度依赖少女力量。81红再复制剪、翠借丝剪气，88翠猜气有额外来源/用途及奇境增幅；只给此猜测C/D，不能把百武物理化、气、势、心解与奇境合成单能力。','E322、E330、E344','后期合作再验证使用分工，并补非魔力气与魔力辅助成长的不同层次。',[102])
revise('C087','80叙述情热早期受情绪支配会敌治我伤，她经管理情绪而由直口自夸辱骂转含蓄自夸/阴阳怪气；不能把早期直率原样锁到后期，也不把苏渣男化玩笑当恋爱事实。89对祭子及白的风险既有同情也有偏见警觉，仍会因友人自我燃尽而难过并邀其共看烟花。','E328、E346、E347','新叙述补性格变化成因，扩展多面性而非凭标签反向归因。')
revise('C103','81翠已借回兽源当探测器，鸢当场见到才获新状态；不让白狼自动同步、不倒推69报告骗人。75改案及88完整内因显示鸢避免无谓屠杀、仍图掳人并保留向首领交代的策略；69低头领命保留为当期行为，现不能再说后续是否改案全未知。','E318、E331、E343、E344','持有人及敌方意图发生阶段变化，新证修正待查状态并保持报告时效。',[102])
revise('R005','76 L21353报心解百武成势，78 L21541解释原繁开百武乘势、新心解百势成武；因此撤回阅读76时的临时卡名错误候选，未分配C号，保留源文自身用名不一。78另现赤鸢，85只有章号无副题，89 L22793及L22822有残句，均不擅自补字。79除翠无人见白兽形与88夏认为翠等并不意外属于叙述和人物观感不同层，不直接判源矛盾。','E319、E323、E326、E336、E342、E345','跨章新证推翻本次未入库候选，保留修订时间、原因和两处原句。')
